using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using UnityEditor;
public static class TestHarvestFeedback {
 static ResourceNode[] targets,originalNodes;static ResourceNode node;static Transform player;static PlayerToolController tools;static PlayerMovement movement;static EquipmentController equipment;static PlayerGatherAnimation actions;static SpriteRenderer visual;static Collider2D solid;static Vector3 rootPos,rootScale;static Quaternion rootRotation;static int stage,index,oldHealth;static double since,start;static bool reacted;static List<string> log=new List<string>();
 public static string Main(){if(!Application.isPlaying)throw new Exception("Play required");player=GameObject.Find("Player").transform;tools=player.GetComponent<PlayerToolController>();movement=player.GetComponent<PlayerMovement>();equipment=player.GetComponent<EquipmentController>();actions=player.GetComponent<PlayerGatherAnimation>();originalNodes=tools.nodes;var all=UnityEngine.Object.FindObjectsByType<ResourceNode>(FindObjectsInactive.Exclude);
 targets=new[]{all.Where(n=>n.type==ResourceType.Wood&&n.acceptsAxe&&!n.Depleted&&n.maxHealth>=3&&UnityEngine.Object.FindAnyObjectByType<ForestNavigation>().Open(UnityEngine.Object.FindAnyObjectByType<ForestNavigation>().Cell(n.HitPoint+Vector2.left*1.05f))).OrderBy(n=>Vector2.Distance(n.transform.position,new Vector2(-27,11))).First(),GameObject.Find("Ruins_MineableStone_01").GetComponent<ResourceNode>(),GameObject.Find("Ruins_MineableStone_02").GetComponent<ResourceNode>()};foreach(var c in UnityEngine.Object.FindObjectsByType<AshenFrontierEncounterController>(FindObjectsInactive.Exclude))c.enabled=false;UnityEngine.Object.FindAnyObjectByType<EnemySpawner>().enabled=false;foreach(var e in EnemyController.ActiveControllers.ToArray())if(e)UnityEngine.Object.Destroy(e.gameObject);index=0;stage=0;start=EditorApplication.timeSinceStartup;Prepare();EditorApplication.update+=Tick;return "Testing real equipped-tool Swing callbacks on tree and both registered grove rocks; yields 2, 3, 4.";}
 static void Prepare(){node=targets[index];node.minYield=node.maxYield=2+index;tools.nodes=new[]{node};visual=node.GetComponent<SpriteRenderer>();solid=node.GetComponent<Collider2D>();rootPos=node.transform.position;rootScale=node.transform.localScale;rootRotation=node.transform.localRotation;var pos=node.HitPoint+Vector2.left*1.05f;player.position=pos;player.GetComponent<Rigidbody2D>().position=pos;player.GetComponent<Rigidbody2D>().linearVelocity=Vector2.zero;Physics2D.SyncTransforms();var inv=player.GetComponent<InventoryController>();var item=inv.FindItem(index==0?"basic_axe":"basic_pickaxe");if(inv.Count(item)==0)inv.Add(item,1);for(int i=0;i<5;i++)if(inv.GetSlot(20+i).Item==item){equipment.Select(i);break;}typeof(PlayerMovement).GetField("<Facing>k__BackingField",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(movement,Vector2.right);oldHealth=node.Health;since=EditorApplication.timeSinceStartup;stage=0;reacted=false;}
 static void Tick(){if(!Application.isPlaying){Finish("INTERRUPTED");return;}var now=EditorApplication.timeSinceStartup;if(now-start>85){Finish("FAIL timeout stage="+stage);return;}if(node.transform.position!=rootPos||node.transform.localScale!=rootScale||node.transform.localRotation!=rootRotation){Finish("FAIL root transform moved");return;}
 if(stage==0&&now-since>.7f&&!actions.Busy){oldHealth=node.Health;if(!tools.Swing(node.type)){Finish("FAIL tool could not select "+node.name);return;}stage=1;since=now;}
 else if(stage==1&&node.Health<oldHealth){var fx=node.GetComponent<ResourceHitFeedback>();reacted=fx&&fx.enabled;log.Add((reacted?"PASS":"FAIL")+" "+node.name+" actual Swing impact health="+node.Health+" reaction="+reacted+" root unchanged; collider="+solid.enabled);
 if(node.Depleted){var popup=Resources.FindObjectsOfTypeAll<HarvestPopup>().LastOrDefault();var text=popup?popup.GetComponentInChildren<Text>().text:"missing";int drops=UnityEngine.Object.FindObjectsByType<ResourcePickup>(FindObjectsInactive.Exclude).Count(p=>p.name.StartsWith(node.name+" Drop "));log.Add((drops==2+index&&text.Contains("+"+drops)?"PASS":"FAIL")+" actual drops="+drops+" popup="+text.Replace("\n"," "));stage=3;}
 else stage=2;since=now;}
 else if(stage==2){if(now-since>.10f&&now-since<.2f)ScreenCapture.CaptureScreenshot("Design/HarvestFeedback/"+(index==0?"Tree":"Stone")+"-Hit.png");if(now-since>.55f&&!actions.Busy){log.Add((visual.enabled&&solid.enabled?"PASS":"FAIL")+" source renderer restored; collider still solid");stage=0;since=now;}}
 else if(stage==3){if(now-since>.13f&&now-since<.23f)ScreenCapture.CaptureScreenshot("Design/HarvestFeedback/Yield-"+(2+index)+".png");if(now-since>1.5f&&!actions.Busy){log.Add((!visual.enabled&&!solid.enabled?"PASS":"FAIL")+" depleted node remains hidden / non-solid after effect");log.Add((Resources.FindObjectsOfTypeAll<HarvestPopup>().Length==0?"PASS":"FAIL")+" popup cleaned up");index++;if(index==targets.Length){Finish("PASS test sequence complete");return;}Prepare();}}
 File.WriteAllLines("Design/HarvestFeedback/Tests.txt",log);
 }
 static void Finish(string result){EditorApplication.update-=Tick;if(tools)tools.nodes=originalNodes;log.Add(result);File.WriteAllLines("Design/HarvestFeedback/Tests.txt",log);}
}
